              width: '100%',
              maxWidth: 1400,
              flex: 1,
              display: 'flex-grow',
              flexDirection: 'column',
              bgcolor: darkMode ? 'grey.800' : 'grey.100',
              borderRadius: 3,
              boxShadow: 3,
              mt: 4,
              mb: 4,
              p: 2,
              minHeight: 0,
